import { closeSync, existsSync, openSync, readFileSync, renameSync, unlinkSync, writeFileSync } from "node:fs";
import { dirname, basename, join } from "node:path";

type Status = "open" | "done";

interface Task {
  id: number;
  title: string;
  status: Status;
  tags: string[];
  due?: string;
  createdAt: string;
  completedAt?: string;
}

interface Database {
  version: 1;
  nextId: number;
  tasks: Task[];
}

class CliError extends Error {}

const databasePath = process.env.TASKBOARD_FILE || ".taskboard.json";

function fail(message: string): never {
  throw new CliError(message);
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isIsoTimestamp(value: unknown): value is string {
  return typeof value === "string" && !Number.isNaN(Date.parse(value));
}

function isDate(value: unknown): value is string {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split("-").map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day;
}

function validateTask(value: unknown): value is Task {
  if (!isPlainObject(value)) return false;
  if (!Number.isSafeInteger(value.id) || (value.id as number) < 1) return false;
  if (typeof value.title !== "string" || value.title.trim() === "") return false;
  if (value.status !== "open" && value.status !== "done") return false;
  if (!Array.isArray(value.tags) || !value.tags.every((tag) => typeof tag === "string" && tag !== "" && tag === tag.trim().toLowerCase())) return false;
  if (new Set(value.tags).size !== value.tags.length) return false;
  if (!isIsoTimestamp(value.createdAt)) return false;
  if (value.due !== undefined && !isDate(value.due)) return false;
  if (value.status === "done" && !isIsoTimestamp(value.completedAt)) return false;
  if (value.status === "open" && value.completedAt !== undefined) return false;
  return true;
}

function validateDatabase(value: unknown): value is Database {
  if (!isPlainObject(value) || value.version !== 1 || !Number.isSafeInteger(value.nextId) || (value.nextId as number) < 1 || !Array.isArray(value.tasks)) return false;
  if (!value.tasks.every(validateTask)) return false;
  const ids = value.tasks.map((task) => task.id);
  return new Set(ids).size === ids.length && ids.every((id) => id < (value.nextId as number));
}

function loadDatabase(): Database {
  if (!existsSync(databasePath)) return { version: 1, nextId: 1, tasks: [] };
  let parsed: unknown;
  try {
    parsed = JSON.parse(readFileSync(databasePath, "utf8"));
  } catch (error) {
    fail(`Cannot read database: ${error instanceof Error ? error.message : String(error)}`);
  }
  if (!validateDatabase(parsed)) fail("Malformed taskboard database");
  return parsed;
}

function saveDatabase(database: Database): void {
  const directory = dirname(databasePath);
  const temporary = join(directory, `.${basename(databasePath)}.${process.pid}.${crypto.randomUUID()}.tmp`);
  let descriptor: number | undefined;
  try {
    descriptor = openSync(temporary, "wx", 0o600);
    writeFileSync(descriptor, `${JSON.stringify(database, null, 2)}\n`, "utf8");
    closeSync(descriptor);
    descriptor = undefined;
    renameSync(temporary, databasePath);
  } catch (error) {
    if (descriptor !== undefined) closeSync(descriptor);
    try { unlinkSync(temporary); } catch {}
    fail(`Cannot write database: ${error instanceof Error ? error.message : String(error)}`);
  }
}

function normalizeTag(tag: string): string {
  return tag.trim().toLowerCase();
}

function parseFlags(args: string[], allowed: Set<string>): Map<string, string> {
  const flags = new Map<string, string>();
  for (let index = 0; index < args.length; index++) {
    const argument = args[index];
    if (!argument.startsWith("--")) fail(`Unexpected argument: ${argument}`);
    const equals = argument.indexOf("=");
    const name = equals < 0 ? argument.slice(2) : argument.slice(2, equals);
    if (!allowed.has(name)) fail(`Unknown flag: --${name}`);
    if (flags.has(name)) fail(`Duplicate flag: --${name}`);
    const value = equals < 0 ? args[++index] : argument.slice(equals + 1);
    if (value === undefined || value.startsWith("--")) fail(`Missing value for --${name}`);
    flags.set(name, value);
  }
  return flags;
}

function parseId(value: string | undefined): number {
  if (value === undefined || !/^[1-9]\d*$/.test(value)) fail("ID must be a positive integer");
  const id = Number(value);
  if (!Number.isSafeInteger(id)) fail("ID must be a safe positive integer");
  return id;
}

function localToday(): string {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, "0");
  const day = String(now.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function run(args: string[]): unknown {
  const [command, ...rest] = args;
  if (!command) fail("Missing command");

  if (command === "add") {
    const flags = parseFlags(rest, new Set(["title", "tags", "due"]));
    const title = flags.get("title")?.trim();
    if (!title) fail("--title is required and must not be empty");
    const due = flags.get("due");
    if (due !== undefined && !isDate(due)) fail("--due must be a valid YYYY-MM-DD date");
    const rawTags = flags.get("tags");
    const tags = rawTags === undefined ? [] : [...new Set(rawTags.split(",").map(normalizeTag).filter(Boolean))];
    const database = loadDatabase();
    const task: Task = { id: database.nextId++, title, status: "open", tags, createdAt: new Date().toISOString() };
    if (due !== undefined) task.due = due;
    database.tasks.push(task);
    saveDatabase(database);
    return task;
  }

  if (command === "list") {
    const flags = parseFlags(rest, new Set(["status", "tag", "overdue"]));
    const status = flags.get("status");
    if (status !== undefined && status !== "open" && status !== "done") fail("--status must be open or done");
    const tag = flags.get("tag");
    if (tag !== undefined && normalizeTag(tag) === "") fail("--tag must not be empty");
    const overdue = flags.get("overdue");
    if (overdue !== undefined && !isDate(overdue)) fail("--overdue must be a valid YYYY-MM-DD date");
    return loadDatabase().tasks
      .filter((task) => status === undefined || task.status === status)
      .filter((task) => tag === undefined || task.tags.includes(normalizeTag(tag)))
      .filter((task) => overdue === undefined || (task.status === "open" && task.due !== undefined && task.due < overdue))
      .sort((left, right) => left.id - right.id);
  }

  if (command === "done") {
    if (rest.length !== 1) fail("Usage: done ID");
    const id = parseId(rest[0]);
    const database = loadDatabase();
    const task = database.tasks.find((candidate) => candidate.id === id);
    if (!task) fail(`Task ${id} not found`);
    if (task.status === "open") {
      task.status = "done";
      task.completedAt = new Date().toISOString();
      saveDatabase(database);
    }
    return task;
  }

  if (command === "delete") {
    if (rest.length !== 1) fail("Usage: delete ID");
    const id = parseId(rest[0]);
    const database = loadDatabase();
    const index = database.tasks.findIndex((task) => task.id === id);
    if (index < 0) fail(`Task ${id} not found`);
    const [deleted] = database.tasks.splice(index, 1);
    saveDatabase(database);
    return deleted;
  }

  if (command === "stats") {
    if (rest.length !== 0) fail("Usage: stats");
    const tasks = loadDatabase().tasks;
    const today = localToday();
    const open = tasks.filter((task) => task.status === "open").length;
    return {
      total: tasks.length,
      open,
      done: tasks.length - open,
      overdue: tasks.filter((task) => task.status === "open" && task.due !== undefined && task.due < today).length,
    };
  }

  fail(`Unknown command: ${command}`);
}

try {
  console.log(JSON.stringify(run(Bun.argv.slice(2))));
} catch (error) {
  const message = error instanceof Error ? error.message : String(error);
  console.log(JSON.stringify({ error: message }));
  console.error(`taskboard: ${message}`);
  process.exitCode = 1;
}

import { afterEach, describe, expect, test } from "bun:test";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";

const cli = join(import.meta.dir, "cli.ts");
const directories: string[] = [];

function board() {
  const directory = mkdtempSync(join(tmpdir(), "taskboard-test-"));
  directories.push(directory);
  const file = join(directory, "board.json");
  const invoke = (...args: string[]) => Bun.spawnSync({
    cmd: ["bun", "run", cli, ...args],
    cwd: directory,
    env: { ...process.env, TASKBOARD_FILE: file },
    stdout: "pipe",
    stderr: "pipe",
  });
  return { file, invoke };
}

function json(result: ReturnType<ReturnType<typeof board>["invoke"]>) {
  return JSON.parse(result.stdout.toString());
}

afterEach(() => {
  for (const directory of directories.splice(0)) rmSync(directory, { recursive: true, force: true });
});

describe("taskboard CLI", () => {
  test("persists, normalizes, filters, completes, and keeps stable ids", () => {
    const { invoke } = board();
    const first = invoke("add", "--title", " First task ", "--tags", " Work,work, HOME ", "--due", "2000-01-01");
    expect(first.exitCode).toBe(0);
    expect(json(first)).toMatchObject({ id: 1, title: "First task", status: "open", tags: ["work", "home"], due: "2000-01-01" });

    expect(json(invoke("add", "--title=Second", "--tags", "home"))).toMatchObject({ id: 2 });
    expect(json(invoke("list", "--tag", "HOME"))).toHaveLength(2);
    expect(json(invoke("list", "--overdue", "2001-01-01"))).toEqual([expect.objectContaining({ id: 1 })]);

    const done = json(invoke("done", "1"));
    const repeated = json(invoke("done", "1"));
    expect(done.status).toBe("done");
    expect(repeated.completedAt).toBe(done.completedAt);
    expect(json(invoke("delete", "2"))).toMatchObject({ id: 2 });
    expect(json(invoke("add", "--title", "Third"))).toMatchObject({ id: 3 });

    const stats = json(invoke("stats"));
    expect(stats).toEqual({ total: 2, open: 1, done: 1, overdue: 0 });
  });

  test("rejects invalid input and preserves a malformed database", () => {
    const { file, invoke } = board();
    for (const args of [
      ["add", "--title", "  "],
      ["add", "--title", "x", "--due", "2025-02-29"],
      ["list", "--wat", "x"],
      ["delete", "1"],
      ["unknown"],
    ]) {
      const result = invoke(...args);
      expect(result.exitCode).not.toBe(0);
      expect(json(result)).toHaveProperty("error");
      expect(result.stderr.toString()).not.toBe("");
    }

    writeFileSync(file, "not-json\n");
    const result = invoke("add", "--title", "must not overwrite");
    expect(result.exitCode).not.toBe(0);
    expect(readFileSync(file, "utf8")).toBe("not-json\n");
  });
});

